(() => {
  const $=id=>document.getElementById(id),stage=$('studio');let scheme='a',selectedTool='board',tab='ai',zoom=100,timer,uploadURL;
  const tools=[['hd','HD','花型高清'],['extract','crop','花型提取'],['recolor','palette','花型配色'],['repeat','repeat','四方连续'],['board','board','灵感搭配'],['delivery','delivery','上架适配'],['copy','copy','商品文案'],['design','design','花型设计']];
  const paths={crop:'M5 2v17h17M2 5h17v17M9 9h8v8H9z',palette:'M20 15a9 9 0 1 0-8 6h2v-4h3a3 3 0 0 0 3-2ZM7 8h.01M14 6h.01M6 14h.01',repeat:'M4 4h16v16H4zM4 12h16M12 4v16',board:'M3 3h18v18H3zM14 3v18M3 15h11M14 10h7',delivery:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',copy:'M5 4h14M12 4v16M8 20h8',design:'m4 20 4-1L20 7l-3-3L5 16zM14 7l3 3'};
  const svg=(name,cls='')=>name==='HD'?'<span class="hd-icon '+cls+'">HD</span>':paths[name]?'<svg class="'+cls+'" viewBox="0 0 24 24" aria-hidden="true"><path d="'+paths[name]+'"/></svg>':'<svg class="'+cls+'" viewBox="0 0 24 24" aria-hidden="true"><use href="#'+name+'-icon"/></svg>';
  const help=(label,text)=>'<button class="help" type="button" aria-label="'+label+'帮助">?<span role="tooltip">'+text+'</span></button>';
  const themes={a:{tag:'自然 · 轻盈 · 专注',description:'奶油白与森林绿，画布优先；AI 与精修分层，常用操作一眼可见。',foot:'A 适合日常使用：保留品牌气质，同时减少空白和重复操作。'},b:{tag:'沉浸 · 克制 · 科技',description:'深色画布与底部指令栏，让作品占据主角；精修参数按需打开。',foot:'B 适合长时间创作：作品更突出，适合高清、提取与配色等以画面为主的工具。'},c:{tag:'清楚 · 有序 · 高效',description:'从素材到方案再到交付，步骤明确；素材、候选和结果可以同时对照。',foot:'C 适合快速上手：流程更明确，适合灵感搭配、上架适配与商品文案。'}};
  function brand(){return '<a class="studio-brand" href="/"><svg viewBox="0 0 32 32" aria-hidden="true"><use href="#brand-leaf"/></svg><span>织景<small>ZHĪJǏNG STUDIO</small></span></a>';}
  function nav(compact=false){return '<nav class="tool-nav" aria-label="工具导航">'+tools.map(([id,icon,label])=>'<button data-tool="'+id+'" aria-pressed="'+(selectedTool===id)+'" title="'+label+'">'+svg(icon)+'<span>'+label+'</span></button>').join('')+'</nav>';}
  function swatches(cls=''){return '<div class="swatches '+cls+'"><i style="--swatch:#7f967a"></i><i style="--swatch:#c6cfb7"></i><i style="--swatch:#e9e4d4"></i><i style="--swatch:#c5a37e"></i><i style="--swatch:#535d4d"></i></div>';}
  function floral(cls=''){return '<svg class="floral '+cls+'" viewBox="0 0 260 330" aria-hidden="true"><rect width="260" height="330" fill="#e9eddf"/><rect width="260" height="330" fill="url(#floral-print)"/></svg>';}
  function materials(){return '<div class="material-items"><button class="material-tile" data-action="upload" aria-label="替换花型参考">'+floral()+'<span>花型参考</span></button><button class="material-tile" data-action="upload" aria-label="替换空间参考"><img src="/assets/scene-photos/natural-v1.png" alt="内置原木卧室参考"><span>空间参考</span></button><button class="material-tile" data-action="upload" aria-label="替换面料质感"><img src="/assets/fabrics/linen.png" alt="内置亚麻质感参考"><span>面料质感</span></button><button class="material-add" data-action="upload" aria-label="添加参考素材">＋</button></div>';}
  function board(){return '<article class="moodboard sample-only" aria-label="内置素材搭配效果示例"><div class="board-meta"><span>ZHĪJǏNG / COLLECTION 01</span><span>SPRING — SUMMER</span></div><div class="board-title"><span>THE EVERYDAY GARDEN</span><h2>风从花园来。</h2><p>自然花型 × 原木空间</p></div><div class="board-photo"><img class="main-reference" src="/assets/scene-photos/natural-v1.png" alt="暖白床品与原木卧室的搭配示例"></div><div class="pattern-paper">'+floral()+'<span>BOTANICAL STUDY / 01</span></div><div class="board-fabric"><img src="/assets/fabrics/linen.png" alt="亚麻织纹"><span>触感，是另一种语言。</span></div><div class="board-palette">'+swatches()+'<span>NATURE, IN A PALETTE.</span></div><span class="board-index">01</span></article>';}
  function empty(){return '<div class="empty-state empty-only"><span class="empty-art">'+floral()+'<b>'+svg('spark')+'</b></span><h2>把灵感放到这里。</h2><p>加入花型、面料或空间参考</p><button class="primary" data-action="upload">'+svg('upload')+' 选择参考素材</button><span>也可以试试右上角的效果示例</span></div>';}
  function canvas(){return '<section class="canvas-card"><header class="canvas-header"><div><span class="status-dot"></span><strong>创作画布</strong><span class="canvas-mode">搭配提案</span></div><div><button class="canvas-icon" data-action="undo" aria-label="撤销示例操作">↶</button><button class="canvas-icon" data-action="redo" aria-label="重做示例操作">↷</button><span class="demo-label">内置示例</span></div></header><div class="canvas-stage">'+board()+empty()+'</div><footer class="canvas-footer"><span>提案 01 <i>·</i> 原木与小花</span><div class="zoom-controls"><button data-action="zoom-out" aria-label="缩小预览">−</button><span class="zoom-value">100%</span><button data-action="zoom-in" aria-label="放大预览">＋</button><button data-action="fit" aria-label="画布适应窗口">⌗</button></div></footer></section>';}
  function prompt(){return '<label class="prompt-label" for="conceptPrompt">创作方向 '+help('创作方向','描述风格、配色和用途即可。预览中的所有操作仅用于比较界面设计。')+'</label><textarea id="conceptPrompt" placeholder="描述希望呈现的风格与搭配…">自然松弛的春夏家纺，鼠尾草绿小花，搭配原木与暖白。</textarea><div class="prompt-chips"><button data-prompt="自然松弛的春夏家纺，鼠尾草绿小花，搭配原木与暖白。">自然松弛</button><button data-prompt="奶油色空间、柔和花型与暖色光线，营造温柔舒适的卧室氛围。">奶油暖调</button><button data-prompt="低饱和蓝灰花型，搭配简洁的家具与留白，适合现代卧室。">现代简约</button></div>';}
  function manual(){return '<div class="manual-content"><label>提案标题<input value="风从花园来。" maxlength="30" id="manualTitle"></label><div class="manual-row"><label>画板比例<select id="manualRatio"><option value="1.32">横版 4:3</option><option value="1">方形 1:1</option></select></label><label>图片排列<select><option>主图 + 细节</option><option>等分排列</option></select></label></div><label>搭配色卡</label>'+swatches()+'<label class="check-label"><input type="checkbox" checked> 完整保留主体</label><button class="secondary full" data-action="export">导出 PNG ↗</button></div>';}
  function assistant(){return '<aside class="assistant"><div class="assistant-tabs" role="tablist" aria-label="创作方式"><button role="tab" data-tab="ai" aria-selected="'+(tab==='ai')+'">'+svg('spark')+' AI 创作</button><button role="tab" data-tab="manual" aria-selected="'+(tab==='manual')+'">精修与导出</button></div><div class="ai-content" '+(tab==='manual'?'hidden':'')+'><div class="section-heading"><h3>参考素材</h3><span>3 / 6</span></div>'+materials()+'<div class="form-divider"></div>'+prompt()+'<div class="assistant-bottom"><div class="generation-summary"><span class="status-dot"></span> AI 搭配提案 <span>1 组</span></div><button class="primary full" data-action="generate">'+svg('spark')+' 生成搭配方案 <b>↗</b></button><small>按当前 AI 服务计费 '+help('生成费用','这是设计预览，不会请求 AI 服务。正式工作台会沿用你配置的 Sub2API。')+'</small></div></div><div class="manual-panel" '+(tab==='ai'?'hidden':'')+'>'+manual()+'</div></aside>';}
  function toolbar(){return '<div class="page-heading"><div><div class="breadcrumb">家纺灵感工具箱 <span>/</span> 创作空间</div><h1 class="current-tool-name">'+tools.find(x=>x[0]===selectedTool)[2]+help('工作台','此页面展示三种界面方向。可以切换工具、查看空白状态和调整示例，但不会提交任何生成任务。')+'</h1></div><div class="page-actions"><span class="saved-state"><i></i> 本机草稿</span><button class="secondary" data-action="save">保存到图库</button><button class="dark-button" data-action="export">导出作品 ↗</button></div></div>';}
  function recent(){return '<div class="recent-strip"><span>最近创作 <b>03</b></span><button class="recent-active" data-action="candidate" data-color="green">'+floral()+'<div><strong>风从花园来</strong><small>自然绿 · 搭配提案</small></div></button><button data-action="candidate" data-color="blue"><img src="/assets/scene-photos/french-v1.png" alt="内置法式卧室示例"><div><strong>温柔的日常</strong><small>奶油蓝 · 系列灵感</small></div></button><button data-action="candidate" data-color="pink"><img src="/assets/scene-photos/warm-v1.png" alt="内置暖白卧室示例"><div><strong>一室柔光</strong><small>杏桃粉 · 空间搭配</small></div></button><button class="all-results" data-action="records">全部记录 ↗</button></div>';}
  function a(){return '<div class="studio-app-header">'+brand()+'<span class="app-space-name">灵感创作空间</span><div class="app-header-right"><a href="/library">我的素材</a><a href="/workspace">完整工作台 ↗</a><span class="avatar">织</span></div></div><div class="a-layout"><aside class="a-sidebar"><a href="/" class="sidebar-home">← 返回首页</a><div class="nav-section-label">创作工具</div>'+nav()+'<div class="sidebar-bottom"><span class="connection"><i></i> Sub2API</span><small>一个空间，完成灵感到作品。</small></div></aside><div class="a-main">'+toolbar()+'<div class="a-work-area">'+canvas()+assistant()+'</div>'+recent()+'</div></div>';}
  function b(){return '<div class="studio-app-header">'+brand()+'<div class="b-title"><span>创作空间 /</span><strong class="current-tool-name">灵感搭配</strong></div><div class="app-header-right"><span class="connection"><i></i> AI 已连接 · 设计示意</span><button class="dark-button" data-action="export">导出作品 ↗</button><span class="avatar">织</span></div></div><div class="b-layout"><aside class="b-sidebar">'+nav(true)+'<a href="/" aria-label="返回首页">⌂</a></aside><div class="b-center"><header class="b-canvas-top"><span>风从花园来 <small> / 创作预览</small></span><div><button class="secondary" data-action="settings">'+svg('sliders')+' 精修设置</button><button class="secondary" data-action="save">保存到图库</button></div></header><div class="b-canvas-area">'+board()+empty()+'<div class="b-zoom"><button data-action="zoom-out" aria-label="缩小预览">−</button><span class="zoom-value">100%</span><button data-action="zoom-in" aria-label="放大预览">＋</button><button data-action="fit" aria-label="适应窗口">⌗</button></div></div><div class="command-dock"><div class="dock-reference"><span>'+svg('image')+' 参考素材 <b>3</b></span>'+materials()+'</div><div class="dock-prompt"><label for="conceptPrompt">让 AI 帮你搭配 '+help('AI 创作','上传花型或空间参考，再描述想要的风格。生成结果经确认后再进入精修。')+'</label><div><textarea id="conceptPrompt" placeholder="描述希望呈现的风格…">自然松弛的春夏家纺，鼠尾草绿小花，搭配原木与暖白。</textarea><button class="primary" data-action="generate">'+svg('spark')+' 生成方案 ↗</button></div><small>按当前 AI 服务计费 · 此页面仅为设计预览</small></div></div><aside class="b-settings" hidden><header><h3>精修与导出</h3><button data-action="close-settings" aria-label="关闭精修设置">×</button></header>'+manual()+'</aside></div><aside class="b-versions"><span>作品版本</span><button class="selected" data-action="candidate" data-color="green">'+floral()+'<small>当前方案</small></button><button data-action="candidate" data-color="blue"><img src="/assets/scene-photos/french-v1.png" alt="内置法式空间"><small>方案 02</small></button><button data-action="candidate" data-color="pink"><img src="/assets/scene-photos/warm-v1.png" alt="内置暖白空间"><small>方案 03</small></button><button class="version-add" data-action="upload">＋</button></aside></div>';}
  function c(){return '<div class="studio-app-header">'+brand()+'<span class="app-space-name">灵感工具箱</span><div class="app-header-right"><a href="/library">我的素材</a><a href="/workspace">完整工作台 ↗</a><span class="avatar">织</span></div></div><div class="c-tool-row">'+nav()+'</div><div class="c-main">'+toolbar()+'<div class="flow-steps" role="group" aria-label="创作步骤"><button data-step="1"><b>✓</b><span>加入参考素材<small>花型、面料与空间</small></span></button><i></i><button data-step="2" aria-pressed="true"><b>2</b><span>AI 生成方案<small>对比与确认</small></span></button><i></i><button data-step="3"><b>3</b><span>精修并交付<small>保存、导出与继续处理</small></span></button></div><div class="c-work-area"><aside class="c-input"><div class="section-heading"><h3>你的创作素材</h3>'+help('创作素材','加入花型、空间与面料参考，再用一句话描述目标。此处上传只在本机显示，不会提交生成。')+'</div>'+materials()+'<button class="secondary full" data-action="upload">＋ 添加素材</button><div class="form-divider"></div>'+prompt()+'<button class="primary full" data-action="generate">'+svg('spark')+' 生成搭配方案</button><small class="charge-note">按当前 AI 服务计费</small></aside><div class="c-result">'+canvas()+'<div class="c-result-actions"><button class="secondary" data-action="save">保存到图库</button><button class="dark-button" data-action="export">导出作品 ↗</button></div></div><aside class="c-candidates"><div class="section-heading"><h3>搭配方向</h3><span>03</span></div><p>先看效果，再选喜欢的方向。</p>'+[['green','自然绿','低饱和花型 · 原木空间'],['blue','奶油蓝','清爽花型 · 简洁空间'],['pink','杏桃粉','暖色花型 · 柔和光线']].map(([color,name,note],i)=>'<button class="candidate-card '+(i===0?'selected':'')+'" data-action="candidate" data-color="'+color+'"><div class="candidate-art '+color+'">'+floral()+'<img src="/assets/scene-photos/'+(['natural','french','warm'][i])+'-v1.png" alt="内置'+name+'搭配示例"></div><div class="candidate-caption"><strong>'+name+'</strong><span>'+(i===0?'✓ 当前':'↗')+'</span></div><small>'+note+'</small></button>').join('')+'<button class="secondary full" data-action="settings">'+svg('sliders')+' 精修当前方案</button><div class="c-manual" hidden>'+manual()+'</div></aside></div></div>';}
  function toast(text){$('previewToast').textContent=text;$('previewToast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('previewToast').classList.remove('visible'),3200);}
  function render(){document.body.dataset.scheme=scheme;stage.innerHTML=({a,b,c})[scheme]();zoom=100;$('conceptTag').textContent=themes[scheme].tag;$('conceptDescription').textContent=themes[scheme].description;$('conceptFootnote').textContent=themes[scheme].foot;document.querySelectorAll('.proposal-switch button').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.scheme===scheme)));}
  document.querySelector('.proposal-switch').onclick=event=>{const button=event.target.closest('[data-scheme]');if(!button)return;scheme=button.dataset.scheme;const url=new URL(location);url.searchParams.set('scheme',scheme);history.replaceState(null,'',url.pathname+url.search);render();};
  document.querySelector('.view-switch').onclick=event=>{const button=event.target.closest('[data-view]');if(!button)return;document.body.dataset.view=button.dataset.view;document.querySelectorAll('.view-switch button').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));};
  stage.addEventListener('click',event=>{
    const tool=event.target.closest('[data-tool]');if(tool){selectedTool=tool.dataset.tool;stage.querySelectorAll('[data-tool]').forEach(item=>item.setAttribute('aria-pressed',String(item===tool)));stage.querySelectorAll('.current-tool-name').forEach(item=>item.firstChild.textContent=tools.find(x=>x[0]===selectedTool)[2]);return toast('正在预览“'+tools.find(x=>x[0]===selectedTool)[2]+'”的导航状态；画布保留同一示例，便于比较布局。');}
    const tabButton=event.target.closest('[data-tab]');if(tabButton){tab=tabButton.dataset.tab;render();return;}
    const prompt=event.target.closest('[data-prompt]');if(prompt){$('conceptPrompt').value=prompt.dataset.prompt;return;}
    const step=event.target.closest('[data-step]');if(step){stage.querySelectorAll('[data-step]').forEach(item=>item.setAttribute('aria-pressed',String(item===step)));return toast(['','第一步：加入参考素材','第二步：生成并确认 AI 方案','第三步：精修、保存与导出'][step.dataset.step]+'（界面预览）');}
    const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
    if(action==='upload')return $('previewUpload').click();
    if(action==='settings'){const settings=stage.querySelector('.b-settings,.c-manual');if(settings)settings.hidden=!settings.hidden;return;}
    if(action==='close-settings'){stage.querySelector('.b-settings').hidden=true;return;}
    if(action.startsWith('zoom-')||action==='fit'){zoom=action==='fit'?100:Math.max(70,Math.min(120,zoom+(action==='zoom-in'?10:-10)));stage.querySelectorAll('.zoom-value').forEach(item=>item.textContent=zoom+'%');stage.querySelectorAll('.moodboard').forEach(item=>item.style.scale=zoom/100);return;}
    if(action==='candidate'){stage.querySelectorAll('[data-action="candidate"]').forEach(item=>{item.classList.toggle('selected',item===button);const marker=item.querySelector('.candidate-caption>span');if(marker)marker.textContent=item===button?'✓ 当前':'↗';});stage.style.setProperty('--flower-color',({green:'#829576',blue:'#758e9c',pink:'#ad8c82'})[button.dataset.color]);stage.querySelectorAll('.board-title h2').forEach(item=>item.textContent=({green:'风从花园来。',blue:'把清风，织进日常。',pink:'日子，慢慢柔软。'})[button.dataset.color]);return;}
    toast(action==='generate'?'这是设计预览，确认方案后再接入实际 AI 创作。':action==='save'?'这是设计预览，未保存到你的素材库。':action==='export'?'这是设计预览；正式版本将沿用现有导出功能。':'这是设计预览，未修改正式工作台的数据。');
  });
  stage.addEventListener('input',event=>{if(event.target.id==='manualTitle')stage.querySelectorAll('.board-title h2').forEach(item=>item.textContent=event.target.value);});
  stage.addEventListener('change',event=>{if(event.target.id==='manualRatio')stage.querySelectorAll('.moodboard').forEach(item=>item.style.aspectRatio=event.target.value);});
  $('previewUpload').onchange=event=>{const file=event.target.files[0];event.target.value='';if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>10*1024*1024)return toast('预览请选择 10 MB 以内的 PNG、JPG 或 WebP。');if(uploadURL)URL.revokeObjectURL(uploadURL);uploadURL=URL.createObjectURL(file);stage.querySelectorAll('.main-reference').forEach(image=>image.src=uploadURL);document.body.dataset.view='sample';document.querySelectorAll('.view-switch button').forEach(item=>item.setAttribute('aria-pressed',String(item.dataset.view==='sample')));toast('图片仅在本机预览，没有上传或生成。');};
  const initial=new URL(location).searchParams.get('scheme');if(['a','b','c'].includes(initial))scheme=initial;render();
})();
